PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY, identity TEXT UNIQUE NOT NULL, data TEXT NOT NULL);
CREATE TABLE packages(id TEXT PRIMARY KEY, job_id TEXT, data TEXT NOT NULL);
CREATE TABLE attempts(id TEXT PRIMARY KEY, job_id TEXT NOT NULL, state TEXT, data TEXT NOT NULL);
CREATE TABLE runs(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE interventions(id TEXT PRIMARY KEY, data TEXT NOT NULL);
COMMIT;
